    let startT = 0, raf1 = 0, raf2 = 0;
    const start = () => { if (!el.getAttribute("src")) { el.preload = "auto"; el.src = el.getAttribute("data-src") || MC_HERO_VIDEO; el.load(); } tryPlay(); };
    if (el.getAttribute("src")) tryPlay();
